def build(d):
    o = d['origin']; t = d['tl']; b = d['board']; v = d['vars']; lg = d['legend']; tr = d['trivia']; e = d['end']
    return {"hook": d['hook'], "ch": [
        {"k": "origin", "t": o[0], "say": o[1], "p": o[2], "pins": o[3], "st": o[4]},
        {"k": "tl", "t": t[0], "say": t[1], "tl": t[2]},
        {"k": "board", "t": b[0], "say": b[1], "cap": b[2], "p": b[3]},
        {"k": "vars", "t": v[0], "say": v[1], "cards": v[2]},
        {"k": "legend", "t": lg[0], "say": lg[1], "items": lg[2]},
        {"k": "trivia", "t": tr[0], "say": tr[1], "cards": tr[2]},
        {"k": "end", "t": e[0], "say": e[1], "p": e[2]}]}

for lang, d in L.items():
    assert len(d['origin'][4]) == len(S['map']['st']), lang
    assert len(d['origin'][3]) == len(S['map']['pts']), lang
    with open(os.path.join(ROOT, lang, 'ludo.json'), 'w') as f: json.dump(build(d), f, ensure_ascii=False)
with open(os.path.join(ROOT, 's', 'ludo.json'), 'w') as f: json.dump(S, f, ensure_ascii=False)
print('ok', sorted(L))
